import * as THREE from './three.js';
// Canvas projection preserves the same 3D world when hardware WebGL is unavailable.
export class SoftwareRenderer{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.shadowMap={};this.pixelRatio=1;this.frame=0;this.cache=new WeakMap();}
 setPixelRatio(r){this.pixelRatio=Math.min(r,1.3);}
 setSize(w,h){this.w=w;this.h=h;this.canvas.width=w*this.pixelRatio;this.canvas.height=h*this.pixelRatio;this.canvas.style.width=w+'px';this.canvas.style.height=h+'px';}
 render(scene,camera){scene.updateMatrixWorld();camera.updateMatrixWorld();const ctx=this.ctx,w=this.w,h=this.h;ctx.setTransform(this.pixelRatio,0,0,this.pixelRatio,0,0);ctx.fillStyle='#91afa2';ctx.fillRect(0,0,w,h);const vp=new THREE.Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse),a=new THREE.Vector3(),b=new THREE.Vector3(),c=new THREE.Vector3(),n=new THREE.Vector3(),ab=new THREE.Vector3(),ac=new THREE.Vector3(),light=new THREE.Vector3(-.4,.85,.35).normalize(),faces=[],sprites=[];
 scene.traverseVisible(o=>{if(o.isSprite){const p=new THREE.Vector3().setFromMatrixPosition(o.matrixWorld),depth=p.distanceTo(camera.position);p.project(camera);if(p.z<1)sprites.push({x:(p.x+1)*w/2,y:(1-p.y)*h/2,w:o.scale.x*h/(depth*.73),h:o.scale.y*h/(depth*.73),img:o.material.map?.image});return;}if(!o.isMesh||!o.geometry?.attributes.position||o.material.opacity<.01)return;const g=o.geometry,pos=g.attributes.position,idx=g.index,mt=o.material,pr=new THREE.Matrix4().multiplyMatrices(vp,o.matrixWorld),len=idx?idx.count:pos.count;const color=mt.color||new THREE.Color('#fff'),er=mt.emissive||new THREE.Color(0),ei=mt.emissiveIntensity||0;for(let j=0;j<len;j+=3){const ia=idx?idx.getX(j):j,ib=idx?idx.getX(j+1):j+1,ic=idx?idx.getX(j+2):j+2;a.fromBufferAttribute(pos,ia);b.fromBufferAttribute(pos,ib);c.fromBufferAttribute(pos,ic);const wa=a.clone().applyMatrix4(o.matrixWorld),wb=b.clone().applyMatrix4(o.matrixWorld),wc=c.clone().applyMatrix4(o.matrixWorld);n.crossVectors(ab.subVectors(wb,wa),ac.subVectors(wc,wa)).normalize();if(mt.side!==THREE.DoubleSide&&n.dot(ab.subVectors(camera.position,wa))<0)continue;a.applyMatrix4(pr);b.applyMatrix4(pr);c.applyMatrix4(pr);if(a.z>1||b.z>1||c.z>1)continue;const x1=(a.x+1)*w/2,y1=(1-a.y)*h/2,x2=(b.x+1)*w/2,y2=(1-b.y)*h/2,x3=(c.x+1)*w/2,y3=(1-c.y)*h/2;if(Math.max(x1,x2,x3)<0||Math.min(x1,x2,x3)>w||Math.max(y1,y2,y3)<0||Math.min(y1,y2,y3)>h)continue;const shade=.72+Math.max(0,n.dot(light))*.38,col=color.clone().multiplyScalar(shade).add(er.clone().multiplyScalar(Math.min(ei,.35)));col.convertLinearToSRGB();const depth=(a.z+b.z+c.z)/3;const low=Math.max(wa.y,wb.y,wc.y)<.06;faces.push({xy:[x1,y1,x2,y2,x3,y3],z:low?depth+2:depth,fill:'rgb('+Math.min(255,col.r*255)+','+Math.min(255,col.g*255)+','+Math.min(255,col.b*255)+')',alpha:mt.transparent?mt.opacity:1});}});
 faces.sort((a,b)=>b.z-a.z);ctx.lineWidth=.45;for(const f of faces){ctx.globalAlpha=f.alpha;ctx.fillStyle=f.fill;ctx.strokeStyle=f.fill;ctx.beginPath();ctx.moveTo(f.xy[0],f.xy[1]);ctx.lineTo(f.xy[2],f.xy[3]);ctx.lineTo(f.xy[4],f.xy[5]);ctx.closePath();ctx.fill();if(f.alpha>.9)ctx.stroke();}ctx.globalAlpha=1;for(const s of sprites)if(s.img)ctx.drawImage(s.img,s.x-s.w/2,s.y-s.h/2,s.w,s.h);
 }
}
